// ── DTO 映射 ──────────────────────────────────────────────────────────

func toApiUser(v userservice.UserView) *userpb.ApiUser {
	out := &userpb.ApiUser{
		Id:          v.ID,
		Username:    v.Username,
		DisplayName: v.DisplayName,
		Role:        v.Role,
		AuthSource:  v.AuthSource,
		CreatedAt:   v.CreatedAt,
		Status:      v.Status,
		AuthVersion: v.AuthVersion,
	}
	if v.Email != "" {
		e := v.Email
		out.Email = &e
	}
	if v.LastLoginAt != "" {
		out.LastLoginAt = &v.LastLoginAt
	}
	if v.DeletedAt != "" {
		out.DeletedAt = &v.DeletedAt
	}
	if v.DeletedBy != "" {
		out.DeletedBy = &v.DeletedBy
	}
	return out
}

// writeUserError 把 service 错误映射到 HTTP 状态。
//
//	400: 参数非法（用户名空/密码<6/角色 invalid）/ 无本地密码
//	403: 非 admin / 删自己
//	404: 用户不存在
//	409: 用户名冲突
func writeUserError(c *app.RequestContext, err error) {
	switch {
	case errors.Is(err, userservice.ErrForbidden):
		c.JSON(consts.StatusForbidden, map[string]string{"error": err.Error()})
	case errors.Is(err, userservice.ErrUserNotFound):
		c.JSON(consts.StatusNotFound, map[string]string{"error": "user not found"})
	case errors.Is(err, userservice.ErrUsernameTaken):
		c.JSON(consts.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, userservice.ErrPasswordNotSet):
		c.JSON(consts.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		// policy 校验错误（ErrUsernameRequired/ErrPasswordTooShort/ErrInvalidRole/ErrCannotDeleteSelf）-> 400。
		c.JSON(consts.StatusBadRequest, map[string]string{"error": err.Error()})
	}
}
